<template>
  <q-badge :color="badgeColor" :label="formattedLabel" :class="['status-badge', `status-badge--${size}`]" />
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

const STATUS_COLORS: Record<string, string> = {
  // Task statuses
  backlog: 'blue-grey',
  todo: 'info',
  in_progress: 'blue-7',
  in_review: 'orange',
  done: 'positive',
  cancelled: 'grey',
  error: 'negative',
  // Mission statuses
  planning: 'blue-grey',
  active: 'blue-7',
  paused: 'warning',
  waiting_approval: 'orange',
  completed: 'positive',
  // Inbox statuses
  pending: 'warning',
  resolved: 'positive',
  dismissed: 'grey',
};

export default defineComponent({
  name: 'StatusBadge',
  props: {
    status: {
      type: String,
      required: true,
    },
    size: {
      type: String as PropType<'sm' | 'md'>,
      default: 'sm',
    },
  },
  computed: {
    badgeColor(): string {
      return STATUS_COLORS[this.status] || 'grey';
    },
    /** Localized status label.  Looks up ``status_<name>`` in the
     *  locale table; falls back to title-cased English when no
     *  translation exists.  Without this the badge always rendered
     *  English (``In Progress``) even when the surrounding UI was
     *  translated, producing rows like
     *  ``Aufgabe aktualisiert · In Review → In Progress`` where
     *  the prefix is German but the badge values stay English. */
    formattedLabel(): string {
      if (!this.status) return '';
      const key = `status_${this.status}`;
      const translated = (this as unknown as { $t: (k: string) => string }).$t(key);
      if (translated && translated !== key) return translated;
      // Fallback: title-case the raw status string.  Used for
      // unknown statuses or locales that haven't been translated.
      return this.status
        .replace(/_/g, ' ')
        .replace(/\b\w/g, (c: string) => c.toUpperCase());
    },
  },
});
</script>

<style scoped lang="scss">
.status-badge--sm {
  font-size: 11px;
  padding: 3px 8px;
}

.status-badge--md {
  font-size: 12px;
  padding: 3px 8px;
}
</style>
